package com.daasuu.mp4compose.filter;  import com.daasuu.mp4compose.utils.GlUtils;  /**  * Created by sudamasayuki on 2017/11/14.  */  public class GlGrayScaleComposeFilter extends GlComposeFilter {     private static final String FRAGMENT_SHADER =             "#extension GL_OES_EGL_image_external : require
" +                     "precision mediump float;
" +                     "varying vec2 vTextureCoord;
" +                     "uniform

target_text:
samplerExternalOES sTexture;
" +                     "const highp vec3 weight = vec3(0.2125, 0.7154, 0.0721);
" +                     "void main() {
" +                     "float luminance = dot(texture2D(sTexture, vTextureCoord).rgb, weight);
" +                     "gl_FragColor = vec4(vec3(luminance), 1.0);
" +                     "}";      public GlGrayScaleComposeFilter() {         super(GlUtils.DEFAULT_VERTEX_SHADER, FRAGMENT_SHADER);     } }
